mapper.select:
SELECT id, region, flag_key, description, enabled, rollout_percent, created_at
FROM feature_flag
WHERE id=#{id} AND region=#{region}

SELECT id, region, flag_key, description, enabled, rollout_percent, created_at
FROM feature_flag
WHERE region=#{region} AND flag_key=#{flagKey}

SELECT id,feature_flag_id,scope_type,scope_id,enabled,rollout_percent,created_at,updated_at
FROM feature_flag_scope WHERE feature_flag_id=#{featureFlagId}
ORDER BY CASE WHEN scope_type='campaign' THEN 1 WHEN scope_type='shop' THEN 2 ELSE 3 END,scope_id,id

SELECT id,feature_flag_id,scope_type,scope_id,enabled,rollout_percent,created_at,updated_at
FROM feature_flag_scope
WHERE feature_flag_id=#{featureFlagId} AND scope_type=#{scopeType} AND scope_id=#{scopeId}

SELECT id, region, name, flag_key, status, created_at
FROM experiment
WHERE id=#{id} AND region=#{region}

SELECT id, experiment_id, user_id, variant, created_at
FROM experiment_assignment
WHERE experiment_id=#{experimentId} AND user_id=#{userId}
